package ua.svitlo.widget.next

import org.json.*
import org.junit.Assert.*
import org.junit.Test
import java.time.*

class Universal170Test {
    @Test fun expiredSourceHonorsFutureServerRefreshWithoutExtendingDisplayFreshness(){assertEquals(1500L,NextRefreshPolicy.deadline(1500,1100,1200));assertFalse(NextRefreshPolicy.due(1200,listOf(NextRefreshPolicy.deadline(1500,1100,1200)),0,0));assertTrue(NextRefreshPolicy.due(1500,listOf(NextRefreshPolicy.deadline(1500,1100,1500)),0,0))}
    @Test fun freshSourceReadsAtEarlierRefreshOrExpiryDeadline(){assertEquals(1200L,NextRefreshPolicy.deadline(1200,1500,1000));assertEquals(1200L,NextRefreshPolicy.deadline(1500,1200,1000))}
    @Test fun refreshUsesServerDeadlineAndDoesNotTreatAttemptAsSuccess(){assertFalse(NextRefreshPolicy.due(1000,listOf(1200),0,0));assertTrue(NextRefreshPolicy.due(1200,listOf(1200),0,0));assertTrue(NextRefreshPolicy.due(1000,listOf(null),0,0));assertFalse(NextRefreshPolicy.due(1300,listOf(1200),1500,0));assertTrue(NextRefreshPolicy.due(1500,listOf(1200),1500,0))}
    @Test fun manualRefreshDoesNotBypassRetryAfter(){assertFalse(NextRefreshPolicy.due(1300,listOf(1200),0,1500,true));assertTrue(NextRefreshPolicy.due(1500,listOf(1700),0,1500,true));assertEquals(3_600_000L,NextRefreshPolicy.backoff(1000))}
    @Test fun wireTimesPreserveOffsetsAndMicroseconds(){assertEquals(Instant.parse("2026-11-04T15:30:58.307525Z"),wireInstant("2026-11-04T15:30:58.307525+00:00"));assertEquals(Instant.parse("2026-11-04T15:30:58Z"),wireInstant("2026-11-04T17:30:58+02:00"));reject{wireInstant("2026-11-04T15:30:58")}}
    @Test fun guideAimMatchesApprovedJavascriptVectors(){val a=GuidePolicy.pointing(GuidePolicy.Box(10.0,100.0,350.0,450.0),GuidePolicy.Box(12.0,500.0,348.0,720.0),90.0,104.0);assertEquals("right",a.side);assertEquals("up",a.pose);assertEquals(116.0,a.offset,.00001);assertTrue(a.hits);val b=GuidePolicy.pointing(GuidePolicy.Box(0.0,730.0,414.0,786.0),GuidePolicy.Box(12.0,410.0,402.0,690.0),103.0,118.0);assertEquals("down-left",b.pose);assertEquals(162.0,b.offset,.00001);assertTrue(b.hits)}
    @Test fun supportRequiresThreeDistinctDaysAndNeverReoffersAfterChoice(){val a=LocalDate.of(2026,11,1);var days=emptyList<LocalDate>();repeat(5){days=GuidePolicy.activeDays(days,a)};assertEquals(1,days.size);assertFalse(GuidePolicy.supportEligible(days,false,false,true,true,false));days=GuidePolicy.activeDays(GuidePolicy.activeDays(days,a.plusDays(1)),a.plusDays(2));assertTrue(GuidePolicy.supportEligible(days,false,false,true,true,false));assertFalse(GuidePolicy.supportEligible(days,true,false,true,true,false));assertFalse(GuidePolicy.supportEligible(days,false,true,true,true,false));assertFalse(GuidePolicy.supportEligible(days,false,false,true,false,false));assertFalse(GuidePolicy.supportEligible(days,false,false,true,true,true))}
    @Test fun measurementSummaryMustMatchSortedExplicitIntervals(){val o=observedFixture();assertEquals(126*60000L,SensorPolicy.observation(o,day).getJSONObject("summary").getLong("offMs"));val invented=JSONObject(o.toString());invented.getJSONObject("observation").getJSONObject("summary").put("offMs",720*60000L);reject{SensorPolicy.observation(invented,day)};val overlapping=JSONObject(o.toString());overlapping.getJSONObject("observation").getJSONArray("intervals").put(JSONObject().put("start",at(10).toString()).put("end",at(11).toString()).put("powerState","on"));reject{SensorPolicy.observation(overlapping,day)};val future=JSONObject(o.toString());future.getJSONObject("observation").getJSONArray("intervals").getJSONObject(0).put("end",at(13).toString());reject{SensorPolicy.observation(future,day)}}
    @Test fun historyRequiresRealKyivDayBounds(){val o=observedFixture();o.put("dayEndUtc",day.plusDays(2).atStartOfDay(NEXT_ZONE).toInstant().toString());reject{SensorPolicy.observation(o,day)}}
    @Test fun postgresAsOfMicrosecondsUseDocumentedMillisecondProjection(){val o=observedFixture().put("asOf",at(12).plusNanos(123456).toString());assertEquals(720*60000L,SensorPolicy.observation(o,day).getJSONObject("summary").getLong("elapsedMs"))}
    @Test fun documentedPhoneProjectionDoesNotRequireAbsentClockQuality(){val now=Instant.parse("2026-11-04T13:00:00Z");val s=JSONObject().put("availability","available").put("freshness","fresh").put("transportState","online").put("reason",JSONObject.NULL).put("coverage",JSONObject().put("kind","explicit_only").put("continuous",false)).put("freshnessSeconds",900).put("lastReceivedAt",now.toString()).put("lastConfirmedAt",now.toString()).put("powerState","off");assertEquals("off",SensorPolicy.signal(s,now));assertEquals("unknown",SensorPolicy.signal(s,now.plusSeconds(901)));s.put("clockQuality","unsynchronized");assertEquals("unknown",SensorPolicy.signal(s,now));s.remove("clockQuality");s.remove("coverage");assertEquals("unknown",SensorPolicy.signal(s,now))}
    @Test fun retryAfterSupportsSecondsDatesAndBoundedDelays(){val now=Instant.parse("2026-11-04T12:00:00Z");assertEquals(120L,NextDeliveryPolicy.retryAfter("120",now));assertEquals(60L,NextDeliveryPolicy.retryAfter("Wed, 4 Nov 2026 12:01:00 GMT",now));assertEquals(0L,NextDeliveryPolicy.retryAfter("invalid",now));assertEquals(86400L,NextDeliveryPolicy.retryAfter("999999",now))}
    @Test fun initialOrUntrustedSignalDoesNotInventSensorTransition(){assertNull(NextDeliveryPolicy.transition("unknown","on","online"));assertNull(NextDeliveryPolicy.transition("on","unknown","online"));assertEquals("lost",NextDeliveryPolicy.transition("off","unknown","offline"));assertEquals("off",NextDeliveryPolicy.transition("on","off","online"));assertNull(NextDeliveryPolicy.transition("on","on","online"))}
    @Test fun sensorGapsAndFutureRemainUnknown(){val rows=listOf(HourFact(at(10),at(10,10),"on"),HourFact(at(10,20),at(10,35),"off"));val facts=SensorHourPolicy.facts(at(10),at(11),at(10,40),rows);assertEquals(listOf("on","unknown","off","unknown","future"),facts.map{it.state});assertEquals(60L,facts.sumOf{Duration.between(it.start,it.end).toMinutes()});assertNull(SensorHourPolicy.transition(at(10),at(11),at(11),rows))}
    @Test fun sensorTransitionRequiresAdjacentConfirmedCoverage(){val rows=listOf(HourFact(at(10),at(10,17),"on"),HourFact(at(10,17),at(11),"off"));assertEquals(at(10,17),SensorHourPolicy.transition(at(10),at(11),at(10,20),rows)?.start);assertNull(SensorHourPolicy.transition(at(10),at(11),at(10,16),rows))}
    @Test fun mergedAutumnHourPreservesFourRealHalfHours(){val autumn=LocalDate.of(2026,10,25);val start=autumn.atStartOfDay(NEXT_ZONE).toInstant().plusSeconds(3*3600);val end=start.plusSeconds(7200);val facts=SensorHourPolicy.facts(start,end,end,(0..3).map{HourFact(start.plusSeconds(it*1800L),start.plusSeconds((it+1)*1800L),if(it%2==0)"on"else"off")});assertEquals(4,facts.size);assertEquals(120L,facts.sumOf{Duration.between(it.start,it.end).toMinutes()})}
    @Test fun numericStringsAndFractionalTimesAreRejected(){val a=fixture();a.put("checkedAt",a.getLong("checkedAt").toString());reject{Universal.parse(a)};val b=fixture();b.put("freshUntil",1.25);reject{Universal.parse(b)}}
    @Test fun catalogDoesNotInventVerifiedDistrict(){val base=JSONObject().put("id","11111111-1111-4111-8111-111111111111").put("label","м. Христинівка");base.put("district",JSONObject().put("name","Уманський район"));assertNull(CatalogItem.parse(base).district);base.getJSONObject("district").put("verified",true).put("source","official-registry");assertEquals("Уманський район",CatalogItem.parse(base).district)}
    private val day=LocalDate.of(2026,10,29)
    private fun at(hour:Int,minute:Int=0)=day.atTime(hour,minute).atZone(NEXT_ZONE).toInstant()
    @Test fun overlappingEmergencyIsCountedOnceAndDisplayMatchesTiles(){val plan=DayPlan(day,listOf(Span(at(10),at(12),Kind.HOURLY),Span(at(10,2),at(12,4),Kind.EMERGENCY),Span(at(16),at(18),Kind.HOURLY),Span(at(20),at(22),Kind.HOURLY)),true,"ready",true);assertEquals(Totals(364,1076,0),plan.totals(false));assertEquals(Totals(360,1080,0),plan.totals(true));assertEquals(6,plan.hours().count{h->h.parts.any{it.kind!=null}});assertEquals(Kind.EMERGENCY,plan.parts().first{it.start==at(10,2)}.kind)}
    @Test fun realHalfHoursSurviveSummary(){val p=DayPlan(day,listOf(Span(at(10,30),at(12),Kind.PLANNED)),true,"ready",true);assertEquals(Totals(90,1350,0),p.totals());assertEquals("1 год 30 хв",durationText(p.totals().off))}
    @Test fun unknownNeverBecomesClear(){val p=DayPlan(day,emptyList(),false,"not_published",true);assertEquals(Totals(0,0,1440),p.totals());assertTrue(p.hours().all{it.parts.all{it.unknown}})}
    @Test fun missingEmergencyEndStaysUnknown(){val p=DayPlan(day,listOf(Span(at(10),null,Kind.EMERGENCY)),true,"ready",true);assertEquals(840,p.totals().unknown);assertEquals(600,p.totals().on)}
    @Test fun springHas23RealHours(){val d=LocalDate.of(2026,3,29);val p=DayPlan(d,emptyList(),true,"ready",true);assertEquals(1380,p.totals().on);assertEquals(23,p.hours().size);assertFalse(p.hours().any{it.label=="03:00"})}
    @Test fun autumnHasOne03WithFourRealHalves(){val d=LocalDate.of(2026,10,25);val p=DayPlan(d,emptyList(),true,"ready",true);assertEquals(1500,p.totals().on);assertEquals(24,p.hours().size);val repeat=p.hours().single{it.label=="03:00"};assertTrue(repeat.repeated);assertEquals(4,repeat.parts.size);assertEquals(7200,Duration.between(repeat.start,repeat.end).seconds)}
    @Test fun categoriesInRepeatedHourKeepChronology(){val d=LocalDate.of(2026,10,25);val start=d.atTime(3,0).atZone(NEXT_ZONE).toInstant();val events=listOf(Kind.HOURLY,Kind.PLANNED,Kind.UNPLANNED,Kind.EMERGENCY).mapIndexed{i,k->Span(start.plusSeconds(i*1800L),start.plusSeconds((i+1)*1800L),k)};val p=DayPlan(d,events,true,"ready",true);assertEquals(Kind.entries.toList(),p.hours().single{it.repeated}.parts.map{it.kind});assertEquals(120,p.totals().off)}
    @Test fun intervalsAtMidnightClipToSelectedDay(){val p=DayPlan(day,listOf(Span(at(0).minusSeconds(3600),at(1),Kind.HOURLY),Span(at(23),at(23).plusSeconds(7200),Kind.PLANNED)),true,"ready",true);assertEquals(120,p.totals().off)}
    @Test fun roundedSubQuarterHourMayDisappearOnlyInDisplay(){val p=DayPlan(day,listOf(Span(at(10,2),at(10,4),Kind.EMERGENCY)),true,"ready",true);assertEquals(2,p.totals(false).off);assertEquals(0,p.totals(true).off)}
    @Test fun explicitNoOutagesCanBeClearWithoutQueue(){val data=fixture("excluded");data.getJSONArray("lines").getJSONObject(0).put("groupCode",JSONObject.NULL);val p=Universal.parse(data);assertNull(p.lines.single().group);assertTrue(p.day(day,null,at(22)).known);assertEquals(1440,p.day(day,null,at(22)).totals().on)}
    @Test fun missingLineDoesNotGuess(){val data=fixture();val lines=data.getJSONArray("lines");lines.put(JSONObject(lines.getJSONObject(0).toString()).put("id","line-b").put("groupCode","2.1"));data.getJSONObject("resolution").put("state","ambiguous");val p=Universal.parse(data);assertNull(p.line(null));assertFalse(p.day(day,null,at(22)).known);assertTrue(p.day(day,"line-b",at(22)).known)}
    @Test fun publishedEmptyIsDifferentFromUnpublished(){val data=fixture();val c=data.getJSONArray("lines").getJSONObject(0).getJSONObject("categories").getJSONObject("hourly");c.getJSONArray("days").getJSONObject(0).put("state","not_published");val d=Universal.parse(data).day(day,null,at(22));assertFalse(d.known);assertEquals("not_published",d.state);assertEquals(1440,d.totals().unknown)}
    @Test fun staleSnapshotCannotClaimLight(){val data=fixture().put("freshUntil",at(21).toEpochMilli());assertFalse(Universal.parse(data).day(day,null,at(22)).known)}
    @Test fun futureCheckedAtFailsClosed(){val data=fixture().put("checkedAt",at(23).toEpochMilli());assertFalse(Universal.parse(data).day(day,null,at(22)).known)}
    @Test fun unknownSchemaRejected(){reject{Universal.parse(fixture().put("schemaVersion",2))}}
    @Test fun unknownStateRejected(){val data=fixture();data.getJSONArray("lines").getJSONObject(0).getJSONObject("categories").getJSONObject("hourly").getJSONArray("days").getJSONObject(0).put("state","all_clear_fake");reject{Universal.parse(data)}}
    @Test fun invalidRangeRejected(){val data=fixture();data.getJSONObject("coverage").put("toDate","2026-11-30");reject{Universal.parse(data)}}
    @Test fun reversedIntervalRejected(){val data=fixture();data.getJSONArray("lines").getJSONObject(0).getJSONObject("categories").getJSONObject("hourly").getJSONArray("days").getJSONObject(0).getJSONArray("intervals").put(JSONObject().put("start",at(12).toEpochMilli()).put("end",at(10).toEpochMilli()));reject{Universal.parse(data)}}
    @Test fun signalExpiresLocallyWithoutNetwork(){val now=at(22);val s=JSONObject().put("availability","available").put("freshness","fresh").put("transportState","online").put("clockQuality","synchronized").put("lastConfirmedAt",now.toString()).put("lastReceivedAt",now.toString()).put("freshnessSeconds",900).put("powerState","on");assertEquals("on",SensorPolicy.signal(s,now));assertEquals("unknown",SensorPolicy.signal(s,now.plusSeconds(901)));s.put("powerState","off");assertEquals("off",SensorPolicy.signal(s,now));s.put("transportState","offline");assertEquals("unknown",SensorPolicy.signal(s,now))}
    @Test fun offlineOrUntrustedNeverMeansOff(){assertEquals("unknown",SensorPolicy.signal(null,at(22)));assertEquals("unknown",SensorPolicy.signal(JSONObject().put("powerState","off"),at(22)))}
    @Test fun qrRejectsUnknownHostAndExtraFields(){val q=JSONObject().put("version",1).put("kind","phone_owner").put("sensorId","11111111-1111-4111-8111-111111111111").put("proof","sp_"+"a".repeat(43));assertEquals("phone_owner",SensorPolicy.qr(q.toString()).getString("kind"));reject{SensorPolicy.qr("https://example.invalid/code")};reject{SensorPolicy.qr(q.put("url","https://example.invalid/").toString())}}
    @Test fun ingestProofNeverGrantsReaderOwnership(){val q=JSONObject().put("version",1).put("kind","phone_owner").put("sensorId","11111111-1111-4111-8111-111111111111").put("proof","st_"+"a".repeat(43));reject{SensorPolicy.qr(q.toString())}}
    private fun reject(block:()->Unit){try{block();fail("Expected invalid input rejection")}catch(e:Exception){assertTrue(e is IllegalArgumentException||e is IllegalStateException||e is JSONException||e is java.time.DateTimeException)}}
    private fun observedFixture():JSONObject {val start=day.atStartOfDay(NEXT_ZONE).toInstant();val end=day.plusDays(1).atStartOfDay(NEXT_ZONE).toInstant();return JSONObject().put("overviewVersion",1).put("date",day.toString()).put("timezone","Europe/Kyiv").put("dayStartUtc",start.toString()).put("dayEndUtc",end.toString()).put("asOf",at(12).toString()).put("observation",JSONObject().put("semantics","explicit_coverage_only").put("complete",true).put("availability","partial").put("through",at(12).toString()).put("points",JSONArray()).put("intervals",JSONArray().put(JSONObject().put("start",at(8,12).toString()).put("end",at(10,18).toString()).put("powerState","off"))).put("summary",JSONObject().put("onMs",0).put("offMs",126*60000L).put("knownMs",126*60000L).put("unknownMs",594*60000L).put("elapsedMs",720*60000L).put("futureMs",720*60000L)))}
    private fun fixture(state:String="resolved"):JSONObject {val cat=JSONObject().put("checkedAt",at(21).toEpochMilli()).put("freshUntil",at(23).toEpochMilli()).put("sourceUpdatedAt",at(20).toEpochMilli()).put("days",JSONArray().put(JSONObject().put("date",day.toString()).put("state","published").put("intervals",JSONArray())));return JSONObject().put("schemaVersion",1).put("addressId","11111111-1111-4111-8111-111111111111").put("operatorId","ua-cherkasy").put("revision","v1").put("timeZone","Europe/Kyiv").put("supportState","available").put("checkedAt",at(21).toEpochMilli()).put("freshUntil",at(23).toEpochMilli()).put("refreshAfter",at(23).toEpochMilli()).put("sourceUpdatedAt",at(20).toEpochMilli()).put("coverage",JSONObject().put("fromDate",day.toString()).put("toDate",day.toString())).put("resolution",JSONObject().put("state",state).put("complete",true)).put("notices",JSONArray()).put("lines",JSONArray().put(JSONObject().put("id","line-a").put("label","Основна лінія").put("groupCode","3.2").put("supportedCategories",JSONArray().put("hourly")).put("categories",JSONObject().put("hourly",cat))))}
}
